import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>单看纸面数据，WebP 是更好的格式。它比 JPG 更小、更清晰、能力更强，而且所有现代浏览器都支持它。可即便如此，很多场景下 JPG 依然是正确的选择。</p>\n<p>原因就是兼容性。当接收方或系统情况不明时，一个到处能打开的格式，胜过一个几乎到处能打开的格式。</p>\n<p>这篇文章会讲清楚，什么时候兼容性比压缩更重要，以及每项工作该怎么在两种格式之间做决定。</p>\n<h2 id=\"compatibility-first\">什么时候兼容性优先？</h2>\n<p>接收方不明时，兼容性永远优先。一张表单、一个客户、一台打印机，或者一台旧电脑前的同事，JPG 一定认，WebP 却可能被拒。</p>\n<p>被拒的代价很高。一次上传失败、一次打印单作废、一封邮件里的图片损坏，浪费的时间远比省下的体积多。</p>\n<p>压缩在受众已知且现代的场景里才占上风。访客都是现代浏览器的网站，用 WebP 确实受益，因为浏览器支持是确定的。</p>\n<p>选格式之前先问一句：谁会打开这个文件？答案是“任何人”，就用 JPG；答案是“现代浏览器”，就用 WebP。</p>\n<h2 id=\"forms-and-portals\">表单、网站平台与官方系统</h2>\n<p>政务网站、招聘平台和学校系统是最严格的去处。它们只接受 JPG 和 PNG，WebP 文件会直接被弹回来。</p>\n<p>这些系统更新很慢。五年前建的平台可能至今没升级过，格式列表还停留在当年的技术水平。</p>\n<p>上传前转成 JPG 是唯一稳妥的做法。表单收得到文件，提交能通过，截止日期也不会错过。</p>\n<p>任何正式提交，先看接受的格式列表。上面没写 WebP 就转成 JPG，别去赌系统“说不定能接受”。</p>\n<h2 id=\"printers-and-print-shops\">打印机与打印店</h2>\n<p>打印机只认 JPG 或 PNG。发给打印店的 WebP 文件可能直接被拒，也可能印出来颜色全错，因为整个打印流程都是围绕老格式建的。</p>\n<p>照片冲印店也一样。很多只接受 JPG 上传，WebP 要么传不上去，要么被冲印店用未知的画质设置转掉。</p>\n<p>任何打印任务都用 90% 或更高画质转成 JPG。打印会放大屏幕上看不出的瑕疵，单张重要图片多占一点空间完全值得。</p>\n<p>发送之前先问打印店想要什么格式。大多数会说 JPG，顺着他们的要求来，就不会白跑一趟或耽误订单。</p>\n<h2 id=\"email-clients\">邮箱客户端与附件</h2>\n<p>邮箱客户端对 WebP 的支持很不一致。有的能显示，有的只显示一个破损图片图标，还有的干脆拒收附件。</p>\n<p>商务邮件里出现破损图片显得很不专业。对方本该看到产品或文档的地方只剩一个缺失的图片，整封邮件的效果都打了折。</p>\n<p>JPG 附件在所有邮箱客户端、所有设备上都能可靠显示。没有任何不确定性，图片一定能完整送达。</p>\n<p>任何用邮件发送的图片都用 JPG。文件是大了点，但显示正常的确定性，远比省下的那点体积值钱。</p>\n<h2 id=\"old-software\">老软件与旧设备</h2>\n<p>老版修图软件、老版办公软件和老操作系统可能根本不认识 WebP。在你的电脑上打得开的文件，换到同事的旧机器上就可能失败。</p>\n<p>办公室、学校和图书馆的共享电脑常常装着老软件。共享盘里的 WebP 文件就是一场赌博，JPG 则是板上钉钉。</p>\n<p>旧手机也一样。发给用着五年前的手机的人，WebP 图片可能显示不出来，JPG 却一定能打开。</p>\n<p>受众里有旧设备时，JPG 是安全选择。它的兼容性覆盖的是有史以来所有设备，而不只是近几年的新设备。</p>\n<h2 id=\"when-compression-wins\">什么时候压缩反而占上风？</h2>\n<p>压缩在现代网站上占上风。访客都是现代浏览器的网站用 WebP 能真正受益，浏览器支持是确定的，省下的体积也是实实在在的。</p>\n<p>一个有二十张图的页面，从 10MB 降到 7MB，访客能明显感觉到加载变快，搜索排名也能从中受益。</p>\n<p>移动流量也是支持压缩的理由。用慢速网络访问的访客马上就能感觉到差别，页面快了，他们停留的时间也更长。</p>\n<p>受众现代的个人博客或网店，WebP 就是正确选择。兼容风险微乎其微，速度收益却很大。</p>\n<h2 id=\"hybrid-approach\">折中办法：两种格式都提供</h2>\n<p>最好的答案常常是两种格式都要。用 HTML 的 picture 元素，给现代浏览器提供 WebP，给老浏览器提供 JPG。</p>\n<p>picture 元素可以先列一个 WebP 来源，再列一个 JPG 备用。现代浏览器会选 WebP，老浏览器回退到 JPG，每个访客都能看到图片。</p>\n<p>这个办法要多占一点存储空间，因为每张图要留两个版本。和大多数访客加载更快、其余访客也能正常看到图的好处比起来，这点成本很小。</p>\n<p>两个版本都从同一个原图生成。转一份 WebP 做现代版，留一份 JPG 做备用版，两边始终保持同步。</p>\n<h2 id=\"converting-strategy\">兼顾两个世界的转换策略</h2>\n<p>母版文件留着画质最好的版本，通常是 JPG 或 PNG。再从母版分别生成上网用的 WebP 和分享用的 JPG。</p>\n<p>别把 WebP 反复转回 JPG。每一次有损转换都会叠加损伤，JPG 一定要从原图生成，而不是从 WebP 生成。</p>\n<p>从网站上收到 WebP 时，如果目的地是表单、打印机或邮件，马上转成 JPG。别等到截止日期才发现格式不兼容。</p>\n<p>文件命名要清楚。hero.webp 和 hero.jpg 放在一个文件夹里一目了然，格式混杂又没有规律的文件夹就很难找了。</p>\n<h2 id=\"measuring-the-tradeoff\">诚实地衡量这笔取舍</h2>\n<p>WebP 通常能省 25% 到 35% 的体积。1MB 的 JPG 变成 700KB 的 WebP，省得确实不少，但也谈不上翻天覆地。</p>\n<p>兼容性风险却是非成即败的失败。上传被拒或图片损坏，不是“差了 30%”，而是彻底用不了，代价远比省下的体积高。</p>\n<p>两边要诚实地权衡。网站图片省 300KB，冒一点兼容风险是值得的；签证申请省同样的 300KB，冒被拒的风险就不值得。</p>\n<p>规则很简单：受众已知且现代就用 WebP，受众不明就用 JPG。格式跟着受众走，而不是跟着潮流走。</p>\n<h2 id=\"future-of-webp\">WebP 兼容性的未来</h2>\n<p>WebP 的支持每年都在变好。现在浏览器全都支持它，操作系统也在跟进，新版 Windows 和 macOS 都能处理 WebP。</p>\n<p>上传表单和打印机变化要慢得多。五年前建的系统，再过五年也未必会加上 WebP 支持，就算会加，也不知道要等到哪天。</p>\n<p>更新的格式 AVIF 已经在和 WebP 争夺同一个位置。格式格局还会继续变，而 JPG 在整个过程中始终是那个备用选择。</p>\n<p>在可预见的未来，JPG 是通用格式，WebP 是现代格式。各用在各自擅长的地方，两者之间自由转换就好。</p>\n<h2 id=\"decision-checklist\">快速决策清单</h2>\n<p>目的地是表单、打印机或邮件？用 JPG，别犹豫。</p>\n<p>目的地是受众已知的现代网站？用 WebP，有条件的话再配一个 JPG 备用。</p>\n<p>受众不明或者新老混杂？用 JPG，兼容性比体积重要。</p>\n<p>图片是用来编辑或归档的？保留原格式，只为交付而转换副本。</p>\n<h2 id=\"compatibility-schools-offices\">学校与办公室里的兼容性</h2>\n<p>学校和办公室里新旧电脑混杂，WebP 支持情况各不相同。教室里的共享电脑可能还装着五年前的软件，打不开 WebP。</p>\n<p>在学校或办公室分享文件，JPG 是安全选择。不管机器多旧、装什么软件，楼里的每台电脑都能打开它。</p>\n<p>老师给学生分享图片之前，先转成 JPG。学生家里的旧电脑能打开 JPG，WebP 文件却可能只显示一个破损图标。</p>\n<p>IT 政策严格的办公室更新软件更慢。WebP 在你的新笔记本上能用，到了共享打印机或会议室电脑上却可能失败。</p>\n<p>拿不准就问一句 IT 部门支持哪些格式。一个简短的问题，能避免演示失败或讲义出问题。</p>\n<h2 id=\"compatibility-government\">与政务系统的兼容性</h2>\n<p>政务系统变化很慢，格式列表还停留在系统建成时的技术水平。五年前建的平台可能只列了 JPG 和 PNG。</p>\n<p>任何正式提交，先看接受的格式列表。上面没写 WebP 就转成 JPG，别去赌系统“说不定能接受”。</p>\n<p>被拒的代价很高。临近截止日期被弹回来，浪费的时间再也找不回来，而 JPG 上传一次就能通过。</p>\n<p>政务系统对文件大小也有严格限制。85% 画质转出来的 JPG 通常远低于上限，同样图片的 PNG 版却可能超标。</p>\n<p>把每张证件照都提前备一份 JPG。文件夹里备好的 JPG 齐全了，截止日期到了就不用临时转换。</p>\n<h2 id=\"compatibility-old-phones\">与旧手机的兼容性</h2>\n<p>旧手机是最常见的兼容性问题。五年前的手机可能显示不了 WebP 图片，打开 JPG 却毫无压力。</p>\n<p>和家人分享图片，JPG 是安全选择。长辈的旧手机能打开 JPG，WebP 文件却只显示一个破损图标，接着就是一通困惑的电话。</p>\n<p>聊天软件有时会帮忙转换，但不是每次都转。同一张 WebP 通过一个软件发过去可能变成了 JPG，通过另一个却原样送达。</p>\n<p>发送前自己先转好，别指望软件帮你转。特意发过去的 JPG 到处能打开，抱着侥幸发出去的 WebP 却只能碰运气。</p>\n<p>选格式前先想想对方的手机用了几年。新手机能处理 WebP，旧手机不行，这个差别就决定了格式。</p>\n<h2 id=\"compatibility-design-software\">与设计软件的兼容性</h2>\n<p>设计软件正在逐步跟上 WebP，但老工具还差得远。Photoshop 现在支持 WebP了，可很多插件和批处理操作还是只认 JPG 或 PNG。</p>\n<p>做设计项目时，先把 WebP 素材转成 JPG 或 PNG 再导入。设计工具处理熟悉的格式不会出意外，项目进行得也更顺畅。</p>\n<p>交给客户的成品，先问对方需要什么格式。客户用的老软件可能打不开 WebP，JPG 却谁都能用，不用多想。</p>\n<p>转换后把 WebP 原件留在项目文件夹里。它们是画质最好的版本，项目以后需要别的格式还能再转。</p>\n<p>在项目笔记里记一行格式选择。简单一句话，就能让下一个接手的人不用猜素材到底是 WebP 还是 JPG。</p>\n<h2 id=\"planning-future-formats\">为未来的格式做规划</h2>\n<p>格式还会一直变，今天的 WebP 可能就是明天的 JPG。AVIF 已经在争夺同一个位置，JPEG XL 也在后面等着。</p>\n<p>母版留着当前最好的格式，每个目的地再转换一份副本。这个策略能扛住任何格式变化，因为母版随时能生成新副本。</p>\n<p>别每次出新格式就把整个存档转一遍。转换会叠加损伤，还会让存储翻倍，而旧格式到处还能打开。</p>\n<p>每年看一次格式格局。花几分钟查一下浏览器支持和工具兼容性，就知道新格式是不是真的能用到实际工作中了。</p>\n<p>目前来看，JPG 依然是通用备用格式，WebP 是现代选择。各用在各自擅长的地方，格局变化时再自由转换就好。</p>\n<h2 id=\"compatibility-cloud-storage\">与云存储的兼容性</h2>\n<p>云存储服务对 WebP 的处理并不一致。Google Drive 原样存放 WebP 文件，其他服务可能能显示缩略图，却打不开完整图片。</p>\n<p>Google 相册原生显示 WebP，因为它本来就是 Google 的格式。照片在 Google 相册里保持 WebP，下载到非 Google 设备时会自动转换。</p>\n<p>Dropbox 能在浏览器里预览 WebP 文件，全分辨率查看时却可能吃力。下载下来在本地转换更可靠。</p>\n<p>iCloud 原样存放 WebP 文件，不做转换。从 iCloud 下载到 Windows 电脑上的 WebP，打开前还是要转换。</p>\n<p>云端存档的话，留着 WebP 原件，分享时再转换副本。原件是画质最好的版本，云端也是存放它们的安全地方。</p>\n<p>这份清单基本覆盖了所有常见情况。拿不准就选 JPG，因为一张到处能打开的文件永远不会错。要转换就打开 <a href=\"/zh/webp-zhuan-jpg/\">WebP 转 JPG 工具</a>，具体步骤可以看<a href=\"/zh/blog/ruhe-jiang-webp-zhuan-huan-wei-jpg/\">如何把 WebP 转换成 JPG</a>。完整指南在<a href=\"/zh/blog/webp-zhuan-jpg-wanquan-zhinan/\">WebP 转 JPG 完全指南</a>里，反方向转换可以用<a href=\"/zh/jpg-zhuan-webp/\">JPG 转 WebP 工具</a>。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"什么时候应该把 WebP 转成 JPG，而不是留着 WebP？","answer":"目的地是表单、打印机、邮件或老软件时就转，因为这些系统经常拒绝 WebP。目的地是受众已知的现代网站时就留着 WebP，更小的文件能让页面更快。格式跟着受众走，而不是跟着潮流走。"},{"question":"JPG 真的比 WebP 更兼容吗？","answer":"是的，差别很明显。JPG 三十年来到处都能用，而 WebP 在一些上传表单、打印机、邮箱客户端和老软件上至今还会失败。现代浏览器都支持 WebP，但浏览器之外的系统还落后着，JPG 赢就赢在这个差距上。"},{"question":"网站上能同时提供 WebP 和 JPG 吗？","answer":"可以，用 HTML 的 picture 元素就行。先列 WebP 来源，再列 JPG 备用，现代浏览器会选更小的文件，老浏览器回退到 JPG。每个访客都能看到图片，大多数人还能享受更快的加载。"},{"question":"WebP 最终会完全取代 JPG 吗？","answer":"短期内大概不会。JPG 用了三十年，有史以来建的系统都支持它，而 WebP 上线多年仍未实现全面支持。AVIF 这样的新格式也在争夺同一个位置。目前来看，JPG 依然是通用备用格式。"},{"question":"为了提交表单把 WebP 转成 JPG，会损失画质吗？","answer":"会损失一点，因为 JPG 比 WebP 更有损，不过画质设到 85% 以上就看不出来了。表单在意的是格式和文件大小，不是逐像素的完美。对正式提交来说，兼容性远比这点画质差别重要。"},{"question":"发邮件给客户的图片，用什么格式最安全？","answer":"JPG 是发邮件最安全的格式，所有客户端都能可靠显示。WebP 附件在某些客户端里可能显示为破损图片，显得很不专业。转成 JPG 文件是大了一点，但显示正常的确定性远比省下的体积值钱。"}];
